select energy_manager.load_cards($cards$[
{"id":"p4-b14-027","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.1: a commercial building has 17,814 m² built-up area, 3,735,640 kWh grid and 2,964,758 kWh captive DG energy per year, and runs 12 h/day for 250 days. What are the EPI and AAHEPI?","back":"EPI about 376 kWh/annum/m². AAHEPI about 125 Wh/h/m².","explain":"Grid and captive energy are both included in total energy. AAHEPI divides by operating hours, so it is a fairer comparison across buildings with different schedules.","steps":[{"prompt":"Find total annual energy.","answer":"3,735,640 + 2,964,758 = 6,700,398 kWh/annum.","explain":"Captive DG energy counts as building energy use in EPI."},{"prompt":"Calculate EPI.","answer":"6,700,398 / 17,814 = 376.1 kWh/annum/m², about 376.","explain":"EPI = total energy ÷ built-up area."},{"prompt":"Find operating hours per year.","answer":"12 h/day × 250 days = 3000 h/annum.","explain":"Operating hours drive the hourly index."},{"prompt":"Calculate AAHEPI.","answer":"376.1 / 3000 × 1000 = 125.4 Wh/h/m², about 125.","explain":"The book's answer is 125 Wh/h/m²."}],"flash":false,"source":"BEE Book 4 Ch 14 p286","order":4599},
{"id":"p4-b14-028","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"What is the U-factor of a wall with layers of outdoor air film 0.04, aluminium siding 0.11, lightweight concrete block 0.35, fibreglass insulation 2.29, gypsum board 0.08 and indoor air film 0.12 (all m²·K/W)?","back":"About 0.33 W/m²·K.","explain":"Layer resistances add in series. The U-factor is the inverse of the total resistance, so the wall's U-factor depends on its total R and not just on its insulation.","steps":[{"prompt":"Add the resistances.","answer":"0.04 + 0.11 + 0.35 + 2.29 + 0.08 + 0.12 = 2.99 m²·K/W.","explain":"All layers, including both air films, are included."},{"prompt":"Take the inverse.","answer":"U = 1 / 2.99 = 0.33 W/m²·K.","explain":"U is the reciprocal of total R."},{"prompt":"Check against the book's value.","answer":"0.33 W/m²·K, the value used in Example 14.2, rounded to two decimals.","explain":"The book rounds U to two decimals before using it in the heat-gain calculation."}],"flash":false,"source":"BEE Book 4 Ch 14 p292","order":4600},
{"id":"p4-b14-029","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what is the conduction heat gain through the 36.3 m² net wall (U 0.33 W/m²·K) at 17:00, when the wall CLTD is 12 °C?","back":"About 144 W. Using only the 9.4 °C dry-bulb difference would give about 113 W.","explain":"CLTD is used instead of the temperature difference, because it includes solar heating of the outside surface and the heat storage of the wall. The book's first 113 W estimate assumed the wall was fully shaded.","steps":[{"prompt":"Find the net wall area.","answer":"Wall plus windows 50.7 m² − windows 14.4 m² = 36.3 m².","explain":"Only the opaque wall is used for wall conduction; windows are counted separately."},{"prompt":"Apply the CLTD formula.","answer":"Q = U × A × CLTD = 0.33 × 36.3 × 12 = 143.9 ≈ 144 W.","explain":"CLTD for wall type 9 at 17:00 is 12 °C."},{"prompt":"Compare with the temperature-difference method.","answer":"Without CLTD: 0.33 × 36.3 × (35 − 25.6) = 113 W. CLTD adds about 31 W for solar heating and storage.","explain":"Solar heating of the outer surface raises the effective temperature difference to 12 °C."}],"flash":false,"source":"BEE Book 4 Ch 14 p293","order":4601},
{"id":"p4-b14-030","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what is the conduction heat gain through the 13.7 m × 18.3 m flat roof (U 0.323 W/m²·K, CLTD 44 °C at 17:00)?","back":"About 3563 W.","explain":"The roof is roof type 2 in the ASHRAE tables. CLTD captures the solar heating on the roof surface and the time-lag storage.","steps":[{"prompt":"Find the roof area.","answer":"13.7 × 18.3 = 250.7 m².","explain":"Area of the flat roof."},{"prompt":"Apply the CLTD formula.","answer":"Q = 0.323 × 250.7 × 44 = 3563 W.","explain":"Same Q = U × A × CLTD form as the wall."},{"prompt":"Compare with the wall gain.","answer":"The roof gives about 25 times the wall gain (3563 W against 144 W) because of its large area and high CLTD.","explain":"Roofs are often the largest conduction gain in a single-storey building."}],"flash":false,"source":"BEE Book 4 Ch 14 p294","order":4602},
{"id":"p4-b14-031","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what is the solar heat gain through 8 double-glazed windows, each 1.2 m × 1.5 m, with shading coefficient 0.74 and SCL 605 W/m² at 17:00?","back":"About 6447 W.","explain":"SCL estimates how fast solar heat reaches the space and is released as sensible heat. The shading coefficient shows the share of incident solar energy that passes through the glass.","steps":[{"prompt":"Find the total glass area.","answer":"8 × (1.2 × 1.5) = 14.4 m².","explain":"Glass area for solar gain."},{"prompt":"Apply the solar gain formula.","answer":"Q = A × SC × SCL = 14.4 × 0.74 × 605 = 6447 W.","explain":"The book's answer is 6447 W."},{"prompt":"Interpret the shading coefficient.","answer":"SC compares the window's solar transmission with a standard reference window. A lower SC means more solar energy is reflected by the outer surface.","explain":"Reducing SC through reflective glass or shading is a direct way to cut solar gain."}],"flash":false,"source":"BEE Book 4 Ch 14 p295","order":4603},
{"id":"p4-b14-032","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what are the sensible and latent infiltration gains for 0.077 m³/s of air, with outdoor 35 °C and 15 g/kg, and indoor 25.6 °C and 10 g/kg?","back":"Sensible about 876 W. Latent about 1159 W.","explain":"Infiltration airflow comes from room volume and air changes per hour. The 1210 and 3010 factors are derived from standard air, so they are used as given in the book.","steps":[{"prompt":"Find the infiltration airflow.","answer":"927.6 m³ × 0.3 / 3600 = 0.077 m³/s.","explain":"Room volume is 13.7 × 18.3 × 3.7 m for this example."},{"prompt":"Find the sensible infiltration gain.","answer":"Qs = 1210 × 0.077 × (35 − 25.6) = 876 W.","explain":"ΔT is outdoor minus indoor dry-bulb temperature."},{"prompt":"Find the latent infiltration gain.","answer":"QL = 3010 × 0.077 × (15 − 10) = 1159 W.","explain":"Humidity ratio difference in g/kg dry air."}],"flash":false,"source":"BEE Book 4 Ch 14 p300","order":4604},
{"id":"p4-b14-033","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what is the internal lighting heat gain for 21.5 W/m² of fluorescent lighting over a 13.7 m × 18.3 m floor, with ballast factor 1.2 and CLF 1.0?","back":"About 6480 W.","explain":"The book rounds 5390 W to 5400 W before applying the ballast factor. The CLF is 1.0 because the set point is raised at night.","steps":[{"prompt":"Find the total lighting load.","answer":"21.5 W/m² × 250.7 m² = 5390 W, rounded in the book to 5400 W.","explain":"Connected lighting load for the floor."},{"prompt":"Apply the ballast factor and CLF.","answer":"Q = 5400 × 1.2 × 1.0 = 6480 W.","explain":"Q = watts × ballast factor × CLF."},{"prompt":"Check the ballast allowance.","answer":"The 20% ballast allowance is already in the 1.2 factor, so do not add it again.","explain":"Adding it twice would overstate the lighting gain by 20%."}],"flash":false,"source":"BEE Book 4 Ch 14 p298","order":4605},
{"id":"p4-b14-034","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: what are the sensible and latent heat gains from 18 people doing moderately active office work (75 W sensible, 55 W latent each, CLF 1.0)?","back":"Sensible 1350 W. Latent 990 W.","explain":"The CLF is 1.0 because the space set point is raised at night, so there is no stored heat to release later. Latent gain has no CLF.","steps":[{"prompt":"Find the sensible gain.","answer":"Qs = 18 × 75 × 1.0 = 1350 W.","explain":"Sensible gain is multiplied by CLF."},{"prompt":"Find the latent gain.","answer":"QL = 18 × 55 = 990 W.","explain":"Latent gain is not multiplied by CLF."},{"prompt":"Check the total people gain.","answer":"Total people gain = 1350 + 990 = 2340 W for 18 people.","explain":"Total gain is the sum of sensible and latent gains, both of which go into the cooling load."}],"flash":false,"source":"BEE Book 4 Ch 14 p297","order":4606},
{"id":"p4-b14-035","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Example 14.2: given a sensible cooling load of 21,623 W and latent load of 2,599 W, what is the sensible heat ratio (SHR), and what supply air flow results at a 12.8 °C supply temperature?","back":"SHR about 0.89 (89% sensible). Supply air flow about 1.4 m³/s.","explain":"SHR shows what share of the load is sensible. The supply air flow then follows from the sensible load and the temperature difference between room and supply air.","steps":[{"prompt":"Calculate SHR.","answer":"SHR = 21,623 / (21,623 + 2,599) = 0.89.","explain":"SHR = sensible ÷ (sensible + latent)."},{"prompt":"Calculate the supply air flow.","answer":"Supply flow = 21,623 / (1210 × (25.6 − 12.8)) = 21,623 / 15,488 = 1.4 m³/s.","explain":"1210 is the density × specific heat factor for air, as in the infiltration formula."},{"prompt":"Check the split.","answer":"SHR 0.89 means about 11% of the load is latent, as the book states.","explain":"Latent load is the share of the load that must be removed to condense moisture."}],"flash":false,"source":"BEE Book 4 Ch 14 p303","order":4607},
{"id":"p4-b14-036","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Solved example: what are the sensible and latent heat gains from 25 people, 40 m² of wall, 15 × 25 m roof and 20 m² of glass in the commercial building, with the book's inputs?","back":"Total cooling load about 34,224 W (sensible 29,690 W, latent 4534 W), using the book's summary table.","explain":"Note the trap: the book's summary table lists wall conduction as 158.4 W, but its own calculation gives 0.33 × (40 − 20) × 12 = 79.2 W. The book's total uses 158.4 W, so the total is likely overstated by about 79 W.","steps":[{"prompt":"Find the external gains.","answer":"Wall 79.2 W; roof 0.323 × 375 × 44 = 5329.5 W; windows 3.56 × 20 × 7 = 498.4 W; solar 20 × 0.74 × 605 = 8954 W.","explain":"Roof area is 15 × 25 = 375 m²."},{"prompt":"Find the internal gains.","answer":"People 1687.5 W sensible + 1375 W latent; lighting 21.5 × 375 × 1.2 × 0.9 = 8707.5 W; equipment sensible 1050 W (coffee maker) + 5.4 × 375 = 2025 W (computers) = 3075 W; the coffee maker's 450 W latent is added to latent gain.","explain":"People CLF 0.9 and lighting CLF 0.9 are given in the example data."},{"prompt":"Find the infiltration gains.","answer":"Airflow = (375 × 3.6 × 0.3) / 3600 = 0.1125 m³/s. Sensible 1279.6 W; latent 2709 W.","explain":"Airflow uses the room volume and 0.3 air changes per hour."},{"prompt":"Add the totals.","answer":"Sensible about 29,690 W (book table), latent 4534 W, total 34,224 W.","explain":"The wall figure used in the book's table (158.4 W) differs from its own calculation (79.2 W)."}],"flash":false,"source":"BEE Book 4 Ch 14 p307","order":4608},
{"id":"p4-b14-037","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Lighting ILER example: a 45 m² room has a room index of 1.93, total circuit load 990 W, average maintained illuminance 700 lux and a target of 46 lux/W/m². What is the ILER, and what is the assessment?","back":"ILER about 0.7. This is in the 0.51 to 0.74 band, so a review is suggested.","explain":"ILER compares the installed lux per watt with the target for this room index and application. The book's result is 0.7.","steps":[{"prompt":"Find the installed load in W/m².","answer":"990 / 45 = 22 W/m².","explain":"Total circuit watts divided by floor area."},{"prompt":"Find the actual lux per W/m².","answer":"700 / 22 = 31.8 lux/W/m².","explain":"Maintained illuminance divided by installed W/m²."},{"prompt":"Calculate the ILER.","answer":"ILER = 31.8 / 46 = 0.69, about 0.7.","explain":"ILER = actual lux/W/m² ÷ target lux/W/m²."},{"prompt":"Assess the result.","answer":"0.51 to 0.74 means review suggested.","explain":"Table 14.6 classes 0.75 or more as satisfactory to good."}],"flash":false,"source":"BEE Book 4 Ch 14 p305","order":4609},
{"id":"p4-b14-038","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"With ILER 0.7 and a 990 W lighting load, running 8 h/day for 300 days, how much lighting energy is wasted per year?","back":"About 713 kWh per year (712.8 kWh).","explain":"Wastage is the share of the installed load above the best possible ILER of 1.0, applied to the operating hours.","steps":[{"prompt":"Find the wasted share of the load.","answer":"1 − ILER = 1 − 0.7 = 0.3.","explain":"Best possible ILER is 1.0."},{"prompt":"Compute annual wastage.","answer":"0.3 × (990 / 1000) × 8 × 300 = 712.8 kWh/annum.","explain":"Wastage = (1 − ILER) × (watts/1000) × operating hours per annum."},{"prompt":"Check the basis of the saving.","answer":"Only the share of load above ILER 1.0 is counted as wastage, so 712.8 kWh/annum is the saving if the installation reached the best possible ILER.","explain":"The saving is an estimate, because a lower ILER can have good reasons such as lower-efficacy lamps."}],"flash":false,"source":"BEE Book 4 Ch 14 p305","order":4610},
{"id":"p4-b14-039","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"What is the lighting power density (LPD) of a building with a 25 kW lighting load and 1500 m² built-up area?","back":"About 16.7 W/m².","explain":"LPD = total operating lighting load ÷ built-up area. This is a direct use of the chapter's definition (review question S-7; the book gives no printed answer).","steps":[{"prompt":"Convert load to watts.","answer":"25 kW = 25,000 W.","explain":"LPD is in W/m²."},{"prompt":"Divide by built-up area.","answer":"25,000 / 1500 = 16.7 W/m².","explain":"Compare with LPD values for the building type."},{"prompt":"Check the basis.","answer":"LPD uses the built-up area of the whole region, so the result is 16.7 W/m² for the building as a whole.","explain":"Use the same area basis when comparing LPD between floors or buildings."}],"flash":false,"source":"BEE Book 4 Ch 14 p309","order":4611},
{"id":"p4-b14-040","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"A building of 8500 m² built-up area uses 3,200,000 kWh per year. What is its EPI?","back":"About 376.5 kWh/annum/m².","explain":"Direct use of the EPI definition (review question S-8; the book gives no printed answer).","steps":[{"prompt":"Divide annual energy by built-up area.","answer":"3,200,000 / 8500 = 376.5 kWh/annum/m².","explain":"EPI = total energy ÷ built-up area."},{"prompt":"Check the units.","answer":"kWh per year divided by m² gives kWh/annum/m², the unit of EPI.","explain":"Keep the unit in the answer so it is not confused with AAHEPI (Wh/h/m²)."},{"prompt":"Compare with Example 14.1.","answer":"Example 14.1 gives EPI about 376 kWh/annum/m² for a different building.","explain":"EPI alone does not show whether the operating hours are long or short; AAHEPI is needed for that."}],"flash":false,"source":"BEE Book 4 Ch 14 p309","order":4612},
{"id":"p4-b14-041","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Review question S-3: what is the conduction heat gain through a 9.3 m² wall with U 0.284 W/m²·K, indoor 21.1 °C and outdoor 30 °C?","back":"About 23.5 W.","explain":"Direct use of Q = U × A × ΔT (the book gives no printed answer for this review question).","steps":[{"prompt":"Find the temperature difference.","answer":"30 − 21.1 = 8.9 °C.","explain":"Outdoor minus indoor dry-bulb temperature."},{"prompt":"Compute the heat gain.","answer":"Q = 0.284 × 9.3 × 8.9 = 23.5 W.","explain":"Plain U × A × ΔT, not CLTD, since no CLTD is given."},{"prompt":"Check the units.","answer":"W/m²·K × m² × K gives watts, so the result is 23.5 W, a small conduction gain.","explain":"Conduction through a small wall is small compared with solar or lighting gains."}],"flash":false,"source":"BEE Book 4 Ch 14 p309","order":4613},
{"id":"p4-b14-042","paper":4,"topic":"Buildings & Commercial","kind":"problem","front":"Review question L-2: if the sensible heat ratio is 0.9 and the latent heat gain is 1900 W, what is the sensible heat gain?","back":"About 17,100 W.","explain":"From SHR = sensible ÷ total, the total is latent ÷ (1 − SHR), so the sensible gain is 0.9 × total (the book gives no printed answer).","steps":[{"prompt":"Find the total heat gain.","answer":"Total = latent ÷ (1 − SHR) = 1900 / 0.1 = 19,000 W.","explain":"Latent is the share left over when SHR is the sensible share."},{"prompt":"Find the sensible gain.","answer":"Sensible = 0.9 × 19,000 = 17,100 W.","explain":"Equivalent to 9 × latent when SHR is 0.9."},{"prompt":"Check the total.","answer":"Sensible 17,100 W + latent 1900 W = 19,000 W, which matches the total.","explain":"The check confirms the SHR arithmetic."}],"flash":false,"source":"BEE Book 4 Ch 14 p309","order":4614},
{"id":"p4-b15-001","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What annual energy use puts a textile unit in the designated consumer category under the Energy Conservation Act?","back":"Textile industries with energy consumption of 3000 MTOE per year and above.","explain":"The threshold is stated in MTOE, so thermal and electrical energy both have to be converted to MTOE before comparing. Textile is one of the process industries the Act brings under designated consumer rules.","flash":true,"source":"BEE Book 4 Ch 15 p313","order":4615},
{"id":"p4-b15-002","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What share of manufacturing cost does energy represent in a modern textile unit?","back":"About 15 to 20 percent.","explain":"Modern textile units need both thermal and electrical energy, so energy is a major cost line. This is why the chapter asks auditors to track energy per kg of yarn or fabric.","flash":true,"source":"BEE Book 4 Ch 15 p313","order":4616},
{"id":"p4-b15-003","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What are the four major stages of textile manufacturing in Figure 15.2?","back":"Yarn fabrication, fabric production (weaving or knitting), wet processing, and garment manufacturing.","explain":"Fibre becomes yarn, yarn becomes fabric, and the grey fabric is then wet processed before garment making. The energy audit concentrates on spinning and weaving and on wet processing.","flash":false,"source":"BEE Book 4 Ch 15 p313","order":4617},
{"id":"p4-b15-004","paper":4,"topic":"Textile energy performance","kind":"fact","front":"List the main steps of cotton yarn production in order.","back":"Opening and blending, cleaning, carding, combing, drawing, roving, spinning.","explain":"Each step turns compressed bales into a progressively finer and more even strand. Combing removes short fibres and gives the most even sliver possible.","flash":false,"source":"BEE Book 4 Ch 15 p314","order":4618},
{"id":"p4-b15-005","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What does the drawing frame do to the card sliver, and how much does it stretch the fibres?","back":"It combines several card slivers into one uniform strand and draws the fibres out about 5 to 6 times.","explain":"Rollers running at successively faster speeds lengthen and align the fibres. Roving then attenuates the strand to about 8 times its length and one-eighth its diameter.","flash":false,"source":"BEE Book 4 Ch 15 p315","order":4619},
{"id":"p4-b15-006","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Name the four yarn spinning technologies. Which one is most used in India?","back":"Ring, rotor, air jet and friction spinning. Ring spinning is the most used in India.","explain":"Ring spinning suits a wide range of yarn types, and rotor spinning is also widely used. The spindle inserts the twist as the drafted strand is wound onto a bobbin.","flash":true,"source":"BEE Book 4 Ch 15 p315","order":4620},
{"id":"p4-b15-007","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Why are warp threads sized before weaving, and at what temperature is the size applied?","back":"To raise tensile strength and smoothness so the warp does not break. The size is applied at 80 to 90 °C, most often natural starch, then dried at 100 to 130 °C.","explain":"The size stays in the cloth until it is removed in later wet processing. PVA, resins, cellulose derivatives and gelatin have also been used as sizes.","flash":false,"source":"BEE Book 4 Ch 15 p316","order":4621},
{"id":"p4-b15-008","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is grey fabric, and what does wet processing do to it?","back":"Grey fabric is the rough fabric straight from weaving or knitting. Wet processing (pre-treatment, dyeing, printing, finishing) improves its appearance and serviceability.","explain":"Grey fabric still has impurities. Wet processing consumes large quantities of water, chemicals and thermal energy, so it is a key focus of the energy audit.","flash":false,"source":"BEE Book 4 Ch 15 p316","order":4622},
{"id":"p4-b15-009","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Which pre-treatment step removes wax, fatty acids and oils, and under what conditions?","back":"Scouring, carried out in alkaline conditions with sodium hydroxide under high pressure and temperature above 100 °C.","explain":"Scouring removes natural impurities before dyeing. The high temperature and pressure let the alkali act quickly on waxes and oils.","flash":true,"source":"BEE Book 4 Ch 15 p317","order":4623},
{"id":"p4-b15-010","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Name two bleaching agents and their working temperatures.","back":"Hypochlorites work at room temperature. Hydrogen peroxide works at about 90 to 95 °C.","explain":"The process conditions depend on the agent. Once bleaching is done, the agent must be fully removed by thorough washing or by enzymes.","flash":false,"source":"BEE Book 4 Ch 15 p317","order":4624},
{"id":"p4-b15-011","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What are the mercerising conditions for cotton, and what does it improve?","back":"Cold sodium hydroxide at about 18 °C for 20 to 40 seconds. It increases tensile strength, lustre and dye uptake.","explain":"The alkali makes the cotton fibre swell, which is what raises dye uptake. The step is short but depends on precise temperature and time.","flash":false,"source":"BEE Book 4 Ch 15 p317","order":4625},
{"id":"p4-b15-012","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Name the important dyeing machines covered in the chapter.","back":"Jigger, winch, padding, mangle and jet dyeing machines.","explain":"The chapter works through a jigger example for steam consumption. Jet dyeing comes up in a review question about condensate discharge.","flash":false,"source":"BEE Book 4 Ch 15 p317","order":4626},
{"id":"p4-b15-013","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is heat setting, at what temperature is it done, and what heats the fabric?","back":"Heat setting brings distorted fabric to the required width and length for dimensional stability. It runs at about 140 to 150 °C, using thermic fluid or steam as the heating medium.","explain":"Stenters and drying machines usually carry out this operation. It is one of the most important finishing steps for dimensional stability.","flash":false,"source":"BEE Book 4 Ch 15 p318","order":4627},
{"id":"p4-b15-014","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Which textile areas use the most energy, apart from non-production loads?","back":"Spinning and weaving, wet processing and garment manufacturing. Compressors and humidification systems also use significant energy.","explain":"Auditors tabulate electricity use separately for spinning and weaving and for wet processing. Non-production systems such as humidification are assessed as well.","flash":false,"source":"BEE Book 4 Ch 15 p318","order":4628},
{"id":"p4-b15-015","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Why is thermal energy in a textile plant expressed in MTOE?","back":"Because fuels have different calorific values, so steam, thermic fluid and fuel use are converted to a common metric tonne of oil equivalent.","explain":"Coal, gas, oil and wood each release different heat per unit. Thermal energy is used mainly in wet processing, so the total is shown in MTOE in the overall energy table.","flash":false,"source":"BEE Book 4 Ch 15 p319","order":4629},
{"id":"p4-b15-016","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Why does the chapter encourage relative indicators such as kWh per kg of product?","back":"Energy use changes with capacity utilisation, so per-unit ratios allow a fair comparison with past years and industry averages.","explain":"Total energy rises and falls with output. Energy cost as a share of total operating expense is another relative indicator the chapter recommends.","flash":false,"source":"BEE Book 4 Ch 15 p319","order":4630},
{"id":"p4-b15-017","paper":4,"topic":"Textile energy performance","kind":"fact","front":"How is electrical energy in kWh converted into MTOE in the textile energy balance?","back":"MTOE = electrical energy (kWh) × 860 / 10⁷. One MTOE is 10⁷ kcal.","explain":"This puts grid and captive electricity on the same MTOE basis as the fuels. It is used in the overall energy table alongside the thermal energy total.","flash":false,"source":"BEE Book 4 Ch 15 p320","order":4631},
{"id":"p4-b15-018","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What are the two benchmarking parameters for textile energy performance, and how do internal and external benchmarking differ?","back":"kWh/kg and kcal/kg of yarn or fabric. Internal benchmarking compares with the plant's own past values; external benchmarking compares with industry average or competitors.","explain":"Both parameters use the generated energy totals, with electrical energy from grid plus captive generation. Benchmarking shows where energy saving opportunities lie.","flash":false,"source":"BEE Book 4 Ch 15 p320","order":4632},
{"id":"p4-b15-019","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Why is performance monitoring of spinning limited to the ring frame?","back":"The ring frame is the single largest energy consumer in spinning.","explain":"Carding, winding and blow room machinery are also energy intensive, and the same approach can be applied to them. The ring frame is the focus because it dominates spinning energy use.","flash":true,"source":"BEE Book 4 Ch 15 p321","order":4633},
{"id":"p4-b15-020","paper":4,"topic":"Textile energy performance","kind":"fact","front":"Describe the stenter in one sentence.","back":"A hot-air dryer in which fabric is held by clips or pins on a chain drive and passes through chambers where air is heated by steam or thermic fluid radiators.","explain":"Besides drying, the stenter pulls fabric to width and is used for chemical finishing, heat setting and curing. Some stenters are also directly fired with natural gas.","flash":false,"source":"BEE Book 4 Ch 15 p321","order":4634},
{"id":"p4-b15-021","paper":4,"topic":"Textile energy performance","kind":"fact","front":"What is the chapter's formula for stenter dryer efficiency?","back":"Efficiency (%) = W × (m_in − m_out) × ((T_out − T_in) + 540) / Q_in × 100. W is bone-dry output (kg/h), m is moisture (kg moisture per kg bone-dry material), T is material temperature (°C), and Q_in is thermal input (kcal/h).","explain":"The 540 kcal/kg is the latent heat of evaporation of water, as used in the chapter's example. Keep W in bone-dry kg/h and Q_in in kcal/h so the units cancel.","flash":false,"source":"BEE Book 4 Ch 15 p323","order":4635}
]$cards$::jsonb);
